36	/// Global settings for the entire workspace
37	#[derive(Debug, Default)]
38	pub struct WorkspaceSettings {
39	    /// Formatter settings applied to all files in the workspaces
40	    pub formatter: FormatSettings,
41	    /// Linter settings applied to all files in the workspace
42	    pub linter: LinterSettings,
43	    /// Language specific settings
44	    pub languages: LanguageListSettings,
45	    /// Filesystem settings for the workspace
46	    pub files: FilesSettings,
47	    /// Analyzer settings
48	    pub organize_imports: OrganizeImportsSettings,
49	    /// overrides
50	    pub override_settings: OverrideSettings,
51	}
