53	impl WorkspaceSettings {
54	    /// Retrieves the settings of the formatter
55	    pub fn formatter(&self) -> &FormatSettings {
56	        &self.formatter
57	    }
58	
59	    /// Whether the formatter is disabled for JavaScript files
60	    pub fn javascript_formatter_disabled(&self) -> bool {
61	        let enabled = self.languages.javascript.formatter.enabled.as_ref();
62	        enabled == Some(&false)
63	    }
64	
65	    /// Whether the formatter is disabled for JSON files
66	    pub fn json_formatter_disabled(&self) -> bool {
67	        let enabled = self.languages.json.formatter.enabled.as_ref();
68	        enabled == Some(&false)
69	    }
70	
71	    /// Whether the formatter is disabled for CSS files
72	    pub fn css_formatter_disabled(&self) -> bool {
73	        let enabled = self.languages.css.formatter.enabled.as_ref();
74	        enabled == Some(&false)
75	    }
76	
77	    /// Retrieves the settings of the linter
78	    pub fn linter(&self) -> &LinterSettings {
79	        &self.linter
80	    }
81	
82	    /// Retrieves the settings of the organize imports
83	    pub fn organize_imports(&self) -> &OrganizeImportsSettings {
84	        &self.organize_imports
85	    }
86	
87	    /// The (configuration)[Configuration] is merged into the workspace
88	    #[tracing::instrument(level = "trace", skip(self))]
89	    pub fn merge_with_configuration(
90	        &mut self,
91	        configuration: PartialConfiguration,
92	        working_directory: Option<PathBuf>,
93	        vcs_path: Option<PathBuf>,
94	        gitignore_matches: &[String],
95	    ) -> Result<(), WorkspaceError> {
96	        // formatter part
97	        if let Some(formatter) = configuration.formatter {
98	            self.formatter = to_format_settings(
99	                working_directory.clone(),
100	                FormatterConfiguration::from(formatter),
101	            )?;
102	        }
103	
104	        // linter part
105	        if let Some(linter) = configuration.linter {
106	            self.linter =
107	                to_linter_settings(working_directory.clone(), LinterConfiguration::from(linter))?;
108	        }
109	
110	        // Filesystem settings
111	        if let Some(files) = to_file_settings(
112	            working_directory.clone(),
113	            configuration.files.map(FilesConfiguration::from),
114	            vcs_path,
115	            gitignore_matches,
116	        )? {
117	            self.files = files;
118	        }
119	
120	        if let Some(organize_imports) = configuration.organize_imports {
121	            self.organize_imports = to_organize_imports_settings(
122	                working_directory.clone(),
123	                OrganizeImports::from(organize_imports),
124	            )?;
125	        }
126	
127	        // javascript settings
128	        if let Some(javascript) = configuration.javascript {
129	            self.languages.javascript = JavascriptConfiguration::from(javascript).into();
130	        }
131	        // json settings
132	        if let Some(json) = configuration.json {
133	            self.languages.json = JsonConfiguration::from(json).into();
134	        }
135	        // css settings
136	        if let Some(css) = configuration.css {
137	            self.languages.css = CssConfiguration::from(css).into();
138	        }
139	
140	        // NOTE: keep this last. Computing the overrides require reading the settings computed by the parent settings.
141	        if let Some(overrides) = configuration.overrides {
142	            self.override_settings =
143	                to_override_settings(working_directory.clone(), overrides, self)?;
144	        }
145	
146	        Ok(())
147	    }
148	
149	    /// It retrieves the severity based on the `code` of the rule and the current configuration.
150	    ///
151	    /// The code of the has the following pattern: `{group}/{rule_name}`.
152	    ///
153	    /// It returns [None] if the `code` doesn't match any rule.
154	    pub fn get_severity_from_rule_code(
155	        &self,
156	        code: &Category,
157	    ) -> Option<biome_diagnostics::Severity> {
158	        let rules = self.linter.rules.as_ref();
159	        if let Some(rules) = rules {
160	            rules.get_severity_from_code(code)
161	        } else {
162	            None
163	        }
164	    }
165	
166	    /// Returns rules taking overrides into account.
167	    pub fn as_rules(&self, path: &Path) -> Option<Cow<Rules>> {
168	        let mut result = self.linter.rules.as_ref().map(Cow::Borrowed);
169	        let overrides = &self.override_settings;
170	        for pattern in overrides.patterns.iter() {
171	            let excluded = pattern.exclude.matches_path(path);
172	            if !excluded && !pattern.include.is_empty() && pattern.include.matches_path(path) {
173	                let pattern_rules = pattern.linter.rules.as_ref();
174	                if let Some(pattern_rules) = pattern_rules {
175	                    result = if let Some(mut result) = result.take() {
176	                        // Override rules
177	                        result.to_mut().merge_with(pattern_rules.clone());
178	                        Some(result)
179	                    } else {
180	                        Some(Cow::Borrowed(pattern_rules))
181	                    };
182	                }
183	            }
184	        }
185	        result
186	    }
187	}
